F='player-core-2'
e={'opcoes':{},'ancestralidades':[],'talentos':[],'lacunas':[]}
def opt(cl,id,name,page,text,skills=[],**extra):
 o=dict(id=id,nome=name,pagina=page,fonte=F,descricao=text,resumo=[text],periciasFixas=skills,**extra);e['opcoes'].setdefault(cl,[]).append(o);return o
opt('alquimista','bombardeiro','Bombardeiro',61,'Aprende duas fórmulas de bombas comuns de1º nível. Ao lançar bomba com dispersão, pode limitar dispersão ao alvo primário. Frascos podem causar frio, eletricidade ou fogo em vez de ácido.')
opt('alquimista','cirurgiao','Cirurgião',62,'Aprende duas fórmulas de elixires comuns de1º nível com cura. Pode usar grau de Manufatura em requisitos de Medicina e modificador de Manufatura nos testes de Medicina. Frasco pode curar criatura viva pelo seu dano inicial: beber ou lançar em alvo voluntário até20pés com Interagir. Ganha coagulante: imunidade temporária à cura por coagulantes por10minutos.')
opt('alquimista','mutagenista','Mutagenista',62,'Aprende duas fórmulas de mutagênicos comuns de1º nível. Ao usar um, recebe PV temporários Inteligência (mínimo0)+metade do nível, por1minuto ou duração do mutagênico, o que acabar primeiro; só recebe novamente após1minuto. Beber frasco suprime uma desvantagem de um mutagênico até início do próximo turno.')
opt('alquimista','toxicologista','Toxicologista',63,'Aprende duas fórmulas de venenos comuns de1º nível. Aplica veneno de ferimento segurado a arma/munição empunhada com uma ação em vez de duas. Venenos infundidos causam ácido contra imunidade a veneno ou se isso for mais prejudicial, conforme mestre. Frascos causam veneno e podem ser aplicados como veneno de ferimento; tornam-se inertes ao fim do turno.')
opt('barbaro','animal','Instinto Animal',75,'Em Fúria recebe ataques desarmados do animal escolhido e não pode usar armas. Fúria ganha morfo/primal. Dados e traços dependem do animal. Especialização aumenta dado um passo e dano de Fúria a5 no nível7,12 com Especialização Maior; resiste a perfurante/cortante. Escolha de animal e ataques ainda exige registro manual.')
opt('barbaro','dragao','Instinto de Dragão',75,'Escolhe dragão. Em Fúria pode elevar dano adicional de2para4 e mudá-lo para o tipo do sopro; ganha tradição e traço de dano pertinente. Especialização aumenta a8 no nível7,16 com Especialização Maior. Resiste a perfurante e tipo do sopro. Tipos são os dragões Remaster; escolha exige registro.')
opt('barbaro','furia','Instinto de Fúria',76,'Dano de Fúria passa de2para3; recebe talento extra de bárbaro de1º nível. Especialização aumenta a7 no nível7,13 com Especialização Maior. Resiste a dano físico de armas, não a ataques desarmados/outras fontes.')
opt('barbaro','gigante','Instinto de Gigante',76,'Pequeno/Médio pode usar arma para Grande; outro tamanho pode usar arma uma categoria acima. Recebe uma arma comum ou acessível de preço até9po sem ajuste de tamanho, grátis e sem revenda antes de runas. Com arma maior, Fúria causa+6 e fica desajeitado1 sem poder ignorar/remover; especialização10 no nível7 e18 com Maior. Resiste a contundente e frio, eletricidade ou fogo à escolha.')
opt('barbaro','espirito','Instinto de Espírito',77,'Em Fúria pode aumentar dano a3 e torná-lo espiritual; só nessa escolha armas/ataques ganham toque fantasma e Fúria ganha divino/espírito. Especialização7 no nível7,13 com Maior. Resiste a vazio e dano de ataques/habilidades de mortos-vivos, qualquer tipo.')
opt('barbaro','supersticao','Instinto de Superstição',77,'É anátema aprender/Conjurar Magia ou usar item ativável para Conjurar Magia; violar remove habilidades/talentos do instinto até1dia de recesso recentrando-se. Em Fúria +2 estado em salvaguardas contra magia e dano de Fúria3, ou4 contra criatura vista conjurando na última hora. Ao entrar, cura PV iguais aos temporários recebidos uma vez a cada10minutos. Aceitar magia/efeito enquanto em Fúria impõe assustado1 que não reduz enquanto afetado. Receber magia não é o antigo anátema. Resistência cobre duas tradições associadas escolhidas conforme livro; detalhamento pendente.')
opt('campeao','profanacao','Profanação',92,'Causa profana e incomum. Escudo Egoísta: reação quando inimigo na aura o fere; resistência ao dano acionador2+metade do nível. Golpes contra agressor causam+1 espiritual até fim do próximo turno (+2 no9,+3 no16). No nível9, se Carisma≥3, resistência é Carisma+metade do nível. No nível11, inimigos na aura recebem−1 estado em ataques contra você até início do próximo turno.',santificacao='profana')
opt('campeao','grandeza','Grandeza',92,'Exige sagrado. Clarão de Grandeza: reação quando inimigo causa dano a aliado, ambos na aura; resistência ao aliado2+nível contra dano acionador e Luz Reveladora no inimigo por1rodada. No nível9 causa espiritual persistente igual a Carisma, irrecuperável enquanto sob sua luz. No nível11, outros inimigos na aura também recebem Luz Reveladora.',santificacao='sagrada')
opt('campeao','iniquidade','Iniquidade',93,'Causa profana e incomum. Vingança Destrutiva: ao inimigo na aura feri-lo, reação aumenta seu dano recebido1d6 e causa1d6 espiritual nele; dados aumentam2d6 no5,3d6 no9,4d6 no12,5d6 no16,6d6 no19. Golpes contra ele+2 espiritual até fim do próximo turno (+4 no9,+6 no16). No nível9 dano inicial também dá espiritual persistente igual a Carisma. No11, demais inimigos na aura sofrem metade do dano da reação.',santificacao='profana')
opt('campeao','justica','Justiça',93,'Golpe Retributivo: reação quando inimigo causa dano a aliado, ambos na aura. Aliado recebe resistência2+nível ao dano acionador; se inimigo ao alcance, Golpe corpo a corpo nele. No nível9, acerto causa espiritual persistente igual a Carisma. No11, aliados na aura com alvo ao alcance podem gastar reação para Golpe com−5. Segue lei/autoridade legítima; explorar outros/trapacear é anátema.')
opt('campeao','libertacao','Libertação',93,'Passo Libertador: reação quando inimigo fere, agarra ou restringe aliado, ambos na aura. Se acionado por dano, resistência2+nível. Aliado pode repetir salvaguarda permitida contra restrição, imobilização/paralisia ou Escapar livre; depois Passo livre se puder mover. No9, quem impunha restrição sofre espiritual persistente igual a Carisma. No11, você e demais aliados na aura também podem dar Passo. Opõe-se à tirania; forçar escolhas dos outros é anátema.')
opt('campeao','obediencia','Obediência',94,'Comando de Ferro: reação divina/emocional/mental quando inimigo na aura o fere. Ele escolhe prostrar-se livremente ou sofrer1d6 mental (2d6 no5,3d6 no9,4d6 no12,5d6 no16,6d6 no19). Golpes contra ele+1 espiritual até fim do próximo turno (+2 no9,+3 no16). No9 recusa também dá espiritual persistente igual a Carisma. No11 outros inimigos escolhem prostrar-se ou dano mínimo dos dados, sem melhorias. Defende hierarquias legítimas; aceitar poder de inferior é anátema.')
opt('campeao','redencao','Redenção',94,'Exige sagrado. Vislumbre de Redenção: reação quando inimigo fere aliado, ambos na aura; escolhe Arrepender-se (aliado sem dano acionador) ou Recusar (resistência2+nível, agressor enfraquecido2 até fim do próximo turno dele). Sem mente/incapaz de arrepender usa Recusar. No9 recusa causa espiritual persistente igual a Carisma. No11 pode estender resistência a todos aliados/você na aura, reduzindo-a em2. Matar sapiente sem oferecer redenção é anátema.',santificacao='sagrada')
opt('investigador','ciencias-alquimicas','Ciências Alquímicas',104,'Treina Manufatura; recebe Manufatura Alquímica, livro de fórmulas e duas fórmulas comuns de1º nível de elixir/ferramenta, além das do talento. Aprende uma nova fórmula por nível. Prepara frascos iguais a Inteligência. Tintura Rápida: uma ação, um frasco, mão livre e ferramentas; cria elixir/ferramenta de seu nível ou menor potente até fim do turno.', ['manufatura'])
opt('investigador','empirismo','Empirismo',105,'Treina perícia de Inteligência à escolha e recebe Isso É Estranho. Inspeção Expedita: ação livre uma vez por10minutos para Recordar Conhecimento, Buscar ou Sentir Motivação.',periciasEscolha=['arcanismo','ocultismo','sociedade','manufatura'])
