# Ancestralidades e heranças.
def anc(id,name,hp,size,boost,flaw,page,text,her):
 a=dict(id=id,nome=name,pv=hp,deslocamento=25,tamanho=size,incrementos=boost,livres=1,descricao=text,resumo=[text],fonte=F,pagina=page,raridade='incomum',herancas=[])
 if flaw:a['defeito']=flaw
 for h in her:
  hid,hn,ht,*more=h;a['herancas'].append(dict(id=id+'-'+hid,nome=hn,descricao=ht,resumo=[ht],fonte=F,pagina=page,**(more[0] if more else {})))
 e['ancestralidades'].append(a)
