# Melhorar espaçamento do conteúdo editorial sem transformar expressões de dado.
import re
skills={'manufatura':'Manufatura','intimidacao':'Intimidação','ocultismo':'Ocultismo','religiao':'Religião','diplomacia':'Diplomacia','enganacao':'Enganação','natureza':'Natureza','sociedade':'Sociedade','arcanismo':'Arcanismo','performance':'Performance','atletismo':'Atletismo','ladroagem':'Ladroagem'}
for opts in e['opcoes'].values():
 for o in opts:
  for key,name in skills.items():o['descricao']=re.sub(r'\b'+key+r'\b',name,o['descricao'])
  o['resumo']=[o['descricao']]
def clean(x):
 if isinstance(x,str):
  x=re.sub(r'(?<![\w])(\d+)(minutos|minuto|horas|hora|dias|dia|pés|po|PV)',r'\1 \2',x)
  x=re.sub(r'(nível|níveis|para|por|igual a|passa a|amaldiçoado|desajeitado|assustado|enfraquecido|estupefato|de|tem|no)(\d)',r'\1 \2',x)
  return x.replace('Repositionar','Reposicionar')
 if isinstance(x,list):return [clean(v) for v in x]
 if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
 return x
e=clean(e)
assert len(e['ancestralidades'])==8
assert sum(len(a['herancas']) for a in e['ancestralidades'])==54
assert len(e['talentos'])==73
assert sum(len(o) for o in e['opcoes'].values())==52
pathlib.Path(__file__).with_name('editorial.json').write_text(json.dumps(e,ensure_ascii=False,indent=2)+'\n')
print('Editorial restaurado:8ancestralidades/54heranças/73talentos/52opções.')
